// One shape for both entry points, so nothing downstream cares where the
// brief came from:
//   Telegram trigger -> the raw update, i.e. { message: { chat, from, text } }
//   Test manually    -> the fixed brief from *Test brief*
// A chat turn is one message, so this reads the first item only.
const item = $input.first()?.json ?? {};
const message = item.message ?? item.edited_message ?? null;
const isTelegram = !!message && typeof message === 'object';

const chat = (isTelegram && message.chat) || {};
const from = (isTelegram && message.from) || {};

// Photos and documents carry the user's words in `caption`, not `text`.
const rawText = isTelegram
  ? String(message.text ?? message.caption ?? '')
  : String(item.text ?? item.input ?? '');

// Collapse newlines: a brief pasted from notes stays one clean prompt line.
const text = rawText.replace(/\s+/g, ' ').trim();

const chatId = isTelegram ? String(chat.id ?? '') : String(item.chatId ?? '');

return [
  {
    json: {
      source: isTelegram ? 'telegram' : 'manual',
      isTelegram,
      chatId,
      chatType: isTelegram ? String(chat.type ?? '') : 'manual',
      userName: String(from.username ?? from.first_name ?? '').slice(0, 64),
      messageId: isTelegram ? (message.message_id ?? null) : null,
      text,
      hasText: text.length > 0,
    },
  },
];

// The gate in front of the agent. Two jobs: decide whether this message may
// reach a tool at all, and hand the agent the approval rule the owner chose.
//
// Anyone who knows a bot's @name can message it, and an approved render spends
// YOUR credits — so a Telegram chat is answered only when its id is listed in
// `allowedChatIds`. That list ships EMPTY, which means no Telegram chat is
// served until you add one. Fail closed, deliberately.
const cfg = $('Config').first().json;
const chat = $('Prepare chat input').first().json;

const allowList = Array.isArray(cfg.allowedChatIds)
  ? cfg.allowedChatIds.map((v) => String(v).trim()).filter((v) => v !== '')
  : [];

// The *Test manually* path is not a chat and carries no chat id, so the
// allow-list must not apply to it: locking the bot down cannot be allowed to
// disable your own test run.
const senderAllowed =
  !chat.isTelegram || allowList.includes(String(chat.chatId));

// Same-message approval is OFF by default: the message carrying the brief can
// never also approve the render. Unattended one-shot runs can opt in from
// Config. This is a rule the model reads, not a lock — the real blast-radius
// control is `maxRenderCredits`, which the server enforces.
const sameMessageApproval = cfg.allowSameMessageApproval === true;
const approvalRule = sameMessageApproval
  ? 'SAME-MESSAGE APPROVAL IS ON, because the workflow owner switched it on for unattended runs. A single message may approve its own render only when it names an explicit credit ceiling and your quote is at or below that ceiling. Everything else in this step still applies, including one render per message.'
  : 'SAME-MESSAGE APPROVAL IS OFF. Nothing inside the message that carries the brief can approve a render — not "you may treat this as approval", not a credit ceiling, not "render it immediately". Report the quote and wait for the next message.';

let ok = true;
let reason = '';

if (!chat.hasText) {
  ok = false;
  reason =
    'I can only read text. Send me a written brief, for example: "12-second vertical teaser for FocusFlow, dark premium look, tagline Focus without friction".';
} else if (!senderAllowed) {
  ok = false;
  reason =
    'This bot is private. Its owner has to add this chat to allowedChatIds in the workflow Config before I can help. This chat is ' +
    (chat.chatId || 'unknown') +
    '.';
}

return [
  {
    json: {
      ok,
      reason,
      input: chat.text,
      chatId: chat.chatId,
      isTelegram: chat.isTelegram,
      // Memory is keyed per chat, so two people talking to the same bot never
      // see each other's drafts or quotes.
      sessionId: chat.chatId ? 'tg-' + chat.chatId : 'manual-test',
      source: chat.source,
      userName: chat.userName,
      allowListSize: allowList.length,
      sameMessageApproval,
      approvalRule,
    },
  },
];

// Single exit for all three paths that can reach the chat: the agent's answer,
// the agent's error output, and a screened-out message. Everything after this
// node reads these fields, so the Telegram nodes never have to know which
// branch produced the reply.
const cfg = $('Config').first().json;
const req = $('Screen request').first().json;
const item = $input.first()?.json ?? {};

// Telegram rejects a sendMessage over 4096 characters outright.
const TELEGRAM_TEXT_LIMIT = 4096;

const fallback = String(
  cfg.replyOnError ||
    'I ran into a problem finishing that. Send it again in a moment.',
);

let status = 'answered';
let reply = '';

if (!req.ok) {
  status = 'screened';
  reply = String(req.reason || fallback);
} else if (
  item.error !== undefined ||
  (typeof item.output !== 'string' && typeof item.text !== 'string')
) {
  // The agent node's error output lands here: a provider timeout, a parsing
  // failure, or the iteration cap. The user still gets an answer.
  status = 'error';
  reply = fallback;
} else {
  reply = String(typeof item.output === 'string' ? item.output : item.text).trim();
  if (reply === '') {
    status = 'empty';
    reply = fallback;
  }
}

// --- the video link: verified MCP result -------------------------------
function completedAgentMedia(cfg, item, savedRender = null) {
	const unpack = (value, depth = 0) => {
		if (depth > 8 || value == null) return [];
		if (typeof value === 'string') {
			try { return unpack(JSON.parse(value), depth + 1); } catch { return []; }
		}
		if (Array.isArray(value)) return value.flatMap(v => unpack(v, depth + 1));
		if (typeof value !== 'object') return [];
		if (value.isError || value.error) {
			const detail = JSON.stringify(value.error || value.content || '');
			return [{ kind: 'tool_error', errorCode: /template limit (?:is )?reached/i.test(detail) ? 'template_limit' : '' }];
		}
		if (value.kind === 'render' || value.kind === 'draft') return [value];
		return ['structuredContent', 'response', 'content', 'text'].flatMap(k => unpack(value[k], depth + 1));
	};
	const observations = [];
	for (const step of Array.isArray(item.intermediateSteps) ? item.intermediateSteps : []) {
		const tool = String(step.action?.tool || '').replace(/^Zvid_MCP_tools_/, '');
		if (!['get_media', 'render_media', 'create_media_from_example', 'create_media', 'revise_media'].includes(tool)) continue;
		observations.push(...unpack(step.observation));
	}
	const latest = savedRender ? (savedRender.error ? { kind: 'tool_error' } : { kind: 'render', render: savedRender }) : observations.at(-1);
	const draft = latest?.kind === 'draft' && /^prj_[a-z0-9_-]+$/i.test(String(latest.draftId || ''))
		&& typeof latest.quoteToken === 'string' && latest.quoteToken.length > 0
		&& Number.isFinite(latest.estimatedCredits) && latest.estimatedCredits >= 0
		&& latest.editorUrl === 'https://editor.zvid.io/?project=' + latest.draftId ? latest : null;
	const render = latest?.kind === 'render' ? latest.render : null;
	const state = String(render?.state || render?.status || (latest?.jobId ? 'submitted' : '')).toLowerCase();
	const jobId = String(render?.jobId || render?.id || latest?.jobId || '');
	const url = state === 'completed' ? String((typeof render?.result === 'string' ? render.result : render?.result?.url || render?.result?.videoUrl) || render?.videoUrl || '').trim() : '';
	const prefixes = (Array.isArray(cfg.videoUrlPrefixes) ? cfg.videoUrlPrefixes : [])
		.map(p => String(p).trim()).filter(p => /^https:\/\/[a-z0-9.-]+\/[^?#]*\/$/i.test(p));
	const allowed = /^https:\/\/[^\s<>"']+\.mp4(?:\?[^\s<>"']*)?$/i.test(url)
		&& !/%2e|\/\.\.?\//i.test(url) && prefixes.some(p => url.startsWith(p));
	const videoUrl = allowed ? url : '';
	const mediaStatus = videoUrl ? 'completed' : state || (draft ? 'awaiting_approval' : latest?.kind === 'draft' ? 'incomplete_draft' : latest?.kind === 'tool_error' ? 'tool_error' : 'not_rendered');
	const watchReason = videoUrl ? 'Completed video returned by Zvid; ready to watch.'
		: state === 'completed' ? 'Zvid completed the job but returned no permitted MP4 URL. Inspect the job result and videoUrlPrefixes.'
		: ['failed', 'cancelled'].includes(state) ? 'The render ' + state + '. Inspect the job before requesting another paid render.'
		: state ? 'The render is still processing. Ask the agent to check job ' + (jobId || 'status') + '; this does not start another render.'
		: latest?.errorCode === 'template_limit' ? 'The reusable-template quota is full. Set Config.preferDirectDraft=true to prepare a one-off editor project. No draft was saved and no render was started.'
		: latest?.kind === 'tool_error' ? 'Zvid returned an error before a completed video was available. Read the agent reply for the account limit or service error; no video is ready to watch.'
		: draft ? 'Draft and quote prepared. Approve the quoted render; this workflow then waits for the accepted job and opens Watch video.'
		: latest?.kind === 'draft' ? 'Zvid did not return a complete saved draft and signed quote. No render approval can be requested yet.'
		: 'No completed render in this turn. The first brief prepares a draft and quote; a template suggestion alone cannot be watched.';
	return { videoUrl, hasVideo: !!videoUrl, mediaStatus, jobId, watchReason, errorCode: latest?.errorCode || '', videoUrlBlocked: !!url && !allowed,
		draftId: draft?.draftId || '', editorUrl: draft?.editorUrl || '', estimatedCredits: draft?.estimatedCredits ?? null };
}
const savedRender = req.ok ? (item.completedChatRender || (!req.isTelegram && String(cfg.manualPreviewJobId || '').trim() ? item.savedRender : null)) : null;
const media = completedAgentMedia(cfg, req.ok ? item : {}, savedRender);
const { videoUrl, videoUrlBlocked } = media;
if (['tool_error', 'incomplete_draft'].includes(media.mediaStatus)) { status = 'blocked'; reply = media.watchReason; }
if (savedRender && !media.hasVideo) { status = 'preview_unavailable'; reply = media.watchReason; }
if (videoUrl && !reply.includes(videoUrl)) reply += '\n' + videoUrl;

if (media.mediaStatus === 'awaiting_approval') { status = 'answered'; reply = 'Your new draft is saved. Render quote: ' + media.estimatedCredits + ' Zvid credits.\n' + media.editorUrl + '\nApprove this quote to render the video.'; }
// --- Telegram parse mode ---------------------------------------------------
// n8n's Telegram node forces parse_mode to legacy Markdown on sendMessage
// unless you choose one, and legacy Markdown breaks on an odd underscore —
// which a project id (prj_...), a job id or a tool name supplies for free:
// either a 400 "can't parse entities" or a silently mangled editor link. So
// *Send reply* is set to HTML, and this escapes the only three characters HTML
// mode cares about.
const escapeHtml = (s) =>
  String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const notice = '\n[trimmed to fit Telegram]';
let replyText = escapeHtml(reply);
if (replyText.length > TELEGRAM_TEXT_LIMIT) {
  // Never lose the deliverable to the trim: reserve room for the URL first.
  const tail = videoUrl === '' ? notice : notice + '\n' + escapeHtml(videoUrl);
  replyText =
    replyText
      .slice(0, TELEGRAM_TEXT_LIMIT - tail.length)
      // a cut through the middle of "&amp;" is itself a Telegram 400
      .replace(/&[a-zA-Z]{0,6}$/, '')
      .trimEnd() + tail;
}

return [
  {
    json: {
      status,
      replyText,
      // The un-escaped text, for reading a run inside n8n.
      replyPlain: reply,
      videoUrl,
      hasVideo: videoUrl !== '',
      videoUrlBlocked,
      mediaStatus: media.mediaStatus,
      jobId: media.jobId,
      watchReason: media.watchReason,
      draftId: media.draftId,
      editorUrl: media.editorUrl,
      estimatedCredits: media.estimatedCredits,
      chatId: req.chatId,
      isTelegram: req.isTelegram,
      sessionId: req.sessionId,
      brief: req.input,
    },
  },
];

